CH = dict(num=14, tag="Maths (Part 2)", theme="Surface area and volume of cuboid, cube, cylinder, cone, pyramid, sphere and hemisphere; estimation",
 title="Math of Space: Surface Area and Volume",
 intro="Solids have a surface that can be covered and an inside that can be filled. This chapter gives the formulas for the surface area and volume of the standard solids, shows where they come from, and uses them to solve everyday problems and to make sensible estimates.",
 big_questions=["How do we measure the surface and the space occupied by a solid?", "How are the formulas for cuboid, cylinder, cone, pyramid and sphere related?", "How can we estimate quantities when exact data are not available?"],
 blocks=[
 ("h2", "Cuboids and Cubes"),
 ("note", "DEFINITION", "A **cuboid** has six rectangular faces and is described by its length **l**, width **w** and height **h**. A **cube** is a cuboid with l = w = h = **a** (the side). **Volume** is the number of unit cubes that fit inside; it is measured in cubic units (cm³, m³)."),
 ("table", ["Solid", "Total surface area (TSA)", "Volume"], [["Cuboid", "2(lw + wh + lh)", "lwh"], ["Cube", "6a²", "a³"]]),
 ("ul", ["Think of a cuboid as many thin rectangular sheets stacked like a pack of cards: **volume = area of base × height**.", "The cube formulas are special cases of the cuboid formulas with l = w = h.", "**Unit conversion:** 1 m³ = 1000 litres, 1000 cm³ = 1 litre."]),
 ("h3", "Same volume, different surface area"),
 ("p", "A cube of side 6 cm and a cuboid 9 cm × 6 cm × 4 cm both have volume **216 cm³**, but their surface areas are **216 cm²** and **228 cm²**. For the same capacity a cube needs less covering material, while a cuboid exposes more area to its surroundings. This idea is used in packaging, cooling and engineering."),
 ("note", "IMPORTANT", "If a cube is cut into many small cubes, the volume stays the same but the total surface area increases greatly. Cutting a 4 cm cube into 1 cm cubes increases the surface area from 96 cm² to 384 cm²."),
 ("h3", "Painted-cube counting (side n, cut into unit cubes, n ≥ 2)"),
 ("table", ["Painted faces", "Number of small cubes"], [["3 (corners)", "8"], ["2 (edges)", "12(n − 2)"], ["1 (faces)", "6(n − 2)²"], ["0 (inside)", "(n − 2)³"]]),
 ("h2", "Right Circular Cylinder"),
 ("note", "DEFINITION", "In a **right circular cylinder** the cross-section parallel to the base is a circle and the axis is **perpendicular** to the base. A **cross-section** is the shape obtained on taking a very thin slice of a solid; a slice parallel to the axis of a cylinder is a rectangle."),
 ("ul", ["Cut the curved surface along a line parallel to the axis and open it out: it is a **rectangle** of sides 2πr and h."]),
 ("table", ["Quantity", "Formula"], [["Curved surface area (CSA)", "2πrh"], ["TSA, closed at both ends", "2πrh + 2πr² = 2πr(h + r)"], ["Surface area, open at one end (tumbler)", "2πrh + πr² = πr(2h + r)"], ["Volume", "πr²h (base area × height)"]]),
 ("p", "Imagine a cylinder as a stack of thin circular discs (like khakhras); the volume is the base area times the height."),
 ("h3", "Worked example"),
 ("steps", [("Step 1", "Read r = 3.5 cm and h = 25 cm for a cylindrical kaleidoscope; use π = 22/7."), ("Step 2", "Only the curved surface needs chart paper, so CSA = 2πrh."), ("Step 3", "CSA = 2 × 22/7 × 3.5 × 25 = **550 cm²**.")]),
 ("note", "NOTE", "Ratios: if r and h change, CSA depends on **r × h** and volume depends on **r² × h**. If r is doubled and h is halved, CSA stays the same while the volume doubles."),
 ("h2", "Cones"),
 ("note", "DEFINITION", "A **right circular cone** is formed when a right triangle is rotated about one of its perpendicular sides. The radius is **r**, the height is **h** and the slant height is **l**, where **l² = h² + r²**."),
 ("ul", ["Cut a cone along a slant edge and unroll it: you get a **sector of a circle** of radius l whose arc length equals the base circumference 2πr.", "Cutting the sector into thin triangles of height l gives CSA = ½ × circumference × l."]),
 ("table", ["Quantity", "Formula"], [["Curved surface area", "πrl"], ["Total surface area", "πrl + πr² = πr(l + r)"], ["Volume", "⅓πr²h"]]),
 ("note", "REMEMBER", "A cone has **one-third** the volume of a cylinder with the same base and height. Experiment: fill the cone with salt and empty it into the cylinder; it takes exactly **three** fills. The factor ⅓ is proved with calculus in Grade 12."),
 ("h3", "Worked example — triangle rotated about a leg"),
 ("steps", [("Step 1", "Triangle 5, 12, 13: 5² + 12² = 13², so it is right-angled."), ("Step 2", "Rotate about the side 12 cm: height h = 12, radius r = 5."), ("Step 3", "Volume = ⅓π × 25 × 12 = **100π cm³**.")]),
 ("h2", "Pyramids"),
 ("p", "A **pyramid** joins every point of a flat base (triangle, square or any shape) to a single point, the **apex**, that lies in a different plane. Examples: the pyramids of Egypt and mountain peaks such as Shivling Peak in Uttarakhand."),
 ("table", ["Quantity", "Rule"], [["Volume", "⅓ × area of base × height (any base shape)"], ["Surface area", "Add the areas of all the faces — no separate formula is needed"]]),
 ("note", "NOTE", "A cone is a pyramid with a circular base; both use the same ⅓ factor."),
 ("h2", "Spheres and Hemispheres"),
 ("note", "DEFINITION", "A **sphere** is the set of all points in space at a fixed distance r (the radius) from a fixed point O (the centre). A **hemisphere** is half a sphere, cut by a plane through the centre; it has one curved surface and one circular base."),
 ("table", ["Solid", "Curved / total surface area", "Volume"], [["Sphere", "4πr²", "⁴⁄₃πr³"], ["Hemisphere", "CSA = 2πr²; TSA = 3πr² (curved + base πr²)", "⅔πr³"]]),
 ("ul", ["**Archimedes' cylinder:** a cylinder of radius r and height 2r tightly fits over a sphere; its curved surface area 2πr × 2r = 4πr² equals the sphere's surface area. (This idea is used in rectangular world maps.)", "**Link with cones:** divide the surface into tiny regions and join them to the centre to get many thin cones of height r, so V = ⅓ × (surface area) × r = ⅓ × 4πr² × r = ⁴⁄₃πr³.", "**String experiment:** string wound over a ball fills four circles of the same radius, verifying 4πr²."]),
 ("h2", "Formula Table"),
 ("table", ["3D shape", "Surface area", "Volume"], [["Cuboid", "2(lw + wh + lh)", "lwh"], ["Cube", "6a²", "a³"], ["Cylinder", "CSA 2πrh; TSA 2πr(h + r)", "πr²h"], ["Cone", "CSA πrl; TSA πr(l + r)", "⅓πr²h"], ["Pyramid", "Sum of face areas", "⅓ × base area × h"], ["Sphere", "4πr²", "⁴⁄₃πr³"], ["Hemisphere", "CSA 2πr²; TSA 3πr²", "⅔πr³"]]),
 ("note", "IMPORTANT", "Use **π = 22/7** (or 3.14) as the question directs. Always write units: cm², m² for areas and cm³, m³ for volumes."),
 ("h2", "Scaling and Melting-Recasting"),
 ("ul", ["If every length is multiplied by **k**, surface area is multiplied by **k²** and volume by **k³** (for example, doubling a sphere's radius gives 4 times the area and 8 times the volume).", "When a solid is **melted and recast**, the volume stays the same: number of pieces = volume of the original ÷ volume of one piece.", "When a solid sinks in water in a container, the **displaced volume** = volume of the solid = base area of container × rise in level."]),
 ("h2", "Areas and Volumes Around Us: Guesstimates"),
 ("p", "A **guesstimate** is a reasoned estimate made when exact data are not available, using assumptions, approximations and everyday knowledge. The answer depends on the assumptions, so different sensible assumptions give different answers."),
 ("steps", [("Step 1", "Guess first (hundreds? thousands?)."), ("Step 2", "List the assumptions, for example the radius of a golgappa and the fraction of it filled with pani."), ("Step 3", "Compute the volumes with the formulas."), ("Step 4", "Divide the total volume by the volume of one item and round sensibly."), ("Step 5", "State the assumptions with the answer.")]),
 ("table", ["Example from the chapter", "Idea"], [["Golgappas from a vessel of pani", "Cylinder volume ÷ pani in one sphere"], ["Tennis balls in a classroom", "Room volume ÷ ball volume (balls do not fill all the space)"], ["Water on the Earth as a thin layer", "Volume = surface area × thickness"]]),
 ("h2", "Typical Exam Questions"),
 ("qa", [("Find the TSA of a cube of volume 64 cm³.", "Side = 4 cm, so TSA = 6 × 16 = 96 cm²."), ("A cone has r = 7 cm and h = 24 cm. Find its slant height and CSA (π = 22/7).", "l = √(49 + 576) = 25 cm; CSA = πrl = 22/7 × 7 × 25 = 550 cm²."), ("Find the volume of a hemisphere of radius 10.5 cm (π = 22/7).", "⅔ × 22/7 × 10.5³ = 2425.5 cm³."), ("Why is the volume of a pyramid ⅓ × base area × height?", "A pyramid has one-third the volume of a prism with the same base and height, just as a cone has one-third the volume of a cylinder."), ("A metal sphere of radius 3 cm is melted into cones of radius 1 cm and height 3 cm. How many cones?", "Sphere = 36π cm³; one cone = π cm³; so 36 cones.")]),
 ],
 takeaways=["Cuboid: **TSA = 2(lw + wh + lh)**, **V = lwh**; cube: **6a²** and **a³**.", "Cylinder: **CSA = 2πrh**, **TSA = 2πr(h + r)**, **V = πr²h**.", "Cone: **l² = h² + r²**, **CSA = πrl**, **V = ⅓πr²h** (one-third of the cylinder).", "Pyramid: **V = ⅓ × base area × height**; surface area is the sum of the faces.", "Sphere: **4πr²** and **⁴⁄₃πr³**; hemisphere: **CSA 2πr², TSA 3πr², V ⅔πr³**.", "Scaling by k multiplies area by k² and volume by k³; melting and recasting keeps volume the same.", "Guesstimates need clear assumptions and a sensible rounded answer."])
